def native():
    global NATIVE_UNAVAILABLE_REASON
    base, _, overload = ATEN_OVERLOAD.rpartition(".")
    try:
        op = getattr(getattr(torch.ops.aten, base), overload or "default")
    except (AttributeError, RuntimeError) as exc:
        NATIVE_UNAVAILABLE_REASON = str(exc)
        return None
    return op if callable(op) else None


def grid():
    out = []
    for b in _BINDINGS:
        out.append({"detail": b["detail"], "dtypes": b["dtypes"]})
    return out


def key_shape(binding):
    return json.dumps(binding["detail"], sort_keys=True)


def build_inputs(binding, dtype, device):
    return _recon.materialize(SCHEMA, binding["detail"], dtype, device)


def unsupported_reason(binding, dtype):
    # Only the (shape, dtype) pairs the benchmark actually ran are valid;
    # e.g. cdist appears in the logs for float32 only.
    if str(dtype) not in binding["dtypes"]:
        return "dtype %s not recorded for this shape" % dtype
    return None


def config(binding, dtype):
    """Rebuild the consumer-side view of this very call.

    baseline.py matches either by real parameter names (path B) or by the
    args/kwargs envelope (path A). C-implemented overloads expose only
    (*args, **kwargs) to inspect, so binding yields the envelope itself; in
    that case emit path A rather than a dict with literal "args"/"kwargs" keys
    nested one level too deep.
    """
    import inspect

    from benchmark.baseline import describe_call

    op = native()
    args, kwargs = build_inputs(binding, dtype, "cuda")
    try:
        bound = inspect.signature(op).bind(*args, **kwargs)
        bound.apply_defaults()
        named = describe_call((), bound.arguments)["kwargs"]
    except (TypeError, ValueError):
        named = None
    if not named or set(named) == {"args", "kwargs"}:
        return {"inputs": describe_call(args, kwargs)}
    return {"inputs": named}
